// Captures the first TLS record emitted by the core, without server responses.
package main
import("context";"crypto/ecdh";"crypto/rand";gotls "crypto/tls";"encoding/hex";"encoding/json";"io";"net";"os";"time";"github.com/xtls/xray-core/transport/internet/tls";"github.com/xtls/xray-core/transport/internet/reality";xnet "github.com/xtls/xray-core/common/net")
func capture(name string,real bool) map[string]string{a,b:=net.Pipe();defer a.Close();defer b.Close();done:=make(chan struct{});ctx,cancel:=context.WithTimeout(context.Background(),time.Second*3);defer cancel();go func(){defer close(done);if real{k,_:=ecdh.X25519().GenerateKey(rand.Reader);reality.UClient(a,&reality.Config{Fingerprint:name,ServerName:"capture.example",PublicKey:k.PublicKey().Bytes(),ShortId:[]byte{1,2,3,4,5,6,7,8}},ctx,xnet.TCPDestination(xnet.DomainAddress("capture.example"),443))}else{c:=tls.UClient(a,&gotls.Config{ServerName:"capture.example",InsecureSkipVerify:true},tls.GetFingerprint(name)).(*tls.UConn);c.HandshakeContext(ctx)}}();b.SetReadDeadline(time.Now().Add(time.Second*3));hdr:=make([]byte,5);if _,err:=io.ReadFull(b,hdr);err!=nil{return map[string]string{"name":name,"error":err.Error()}};body:=make([]byte,int(hdr[3])<<8|int(hdr[4]));_,err:=io.ReadFull(b,body);b.Close();<-done;if real{name="reality/"+name};r:=map[string]string{"name":name,"hex":hex.EncodeToString(append(hdr,body...))};if err!=nil{r["error"]=err.Error()};return r}
func main(){var rows []map[string]string;for _,n:=range []string{"chrome","","safari","firefox","edge","randomized"}{rows=append(rows,capture(n,false))};rows=append(rows,capture("chrome",true),capture("",true));json.NewEncoder(os.Stdout).Encode(rows)}
